import {createCase,pools,measure,faults,tests} from './model.mjs';
import {recommendation} from './guided.mjs';
import {context} from './guided-progress.mjs';
export function createExam(random=Math.random){const keys=[...pools.diagnosis];for(let i=keys.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[keys[i],keys[j]]=[keys[j],keys[i]];}return {id:crypto.randomUUID(),date:new Date().toISOString(),index:0,done:false,cases:keys.slice(0,3).map(fault=>({s:{...createCase('diagnosis'),fault,key:'crank'},log:[],answer:null}))};}
export function examMeasure(exam,id){if(exam.done||!tests[id])return;const c=exam.cases[exam.index];if(c.answer||c.log.some(e=>e.choice===id)||c.log.length>=7)return;const before=context(c.s),r=recommendation(c.s),result=measure(c.s,id);c.log.push({round:c.log.length+1,choice:id,before,correct:r.choices.includes(id),recommended:r.choices,reason:r.reason,result});return result;}
export function submitCase(exam,answer){const c=exam.cases[exam.index];if(exam.done||c.answer||!pools.diagnosis.includes(answer))return false;c.answer=answer;c.supported=faults[c.s.fault].tests.every(t=>c.s.measured.includes(t));c.correct=answer===c.s.fault;c.score=Math.max(0,100-10*c.log.filter(e=>!e.correct).length-(c.correct?0:40)-(c.supported?0:20));if(exam.index===exam.cases.length-1){exam.done=true;exam.completedAt=new Date().toISOString();}else exam.index++;return true;}
export function examRecords(exam){if(!exam.done)return [];return exam.cases.map((c,i)=>({id:exam.id+'-'+i,date:exam.date,completedAt:exam.completedAt,status:'complete',score:c.score,level:'challenge',source:'weekly-exam',hints:0,hintLog:[],log:structuredClone(c.log),remediation:!c.correct||!c.supported?faults[c.s.fault].tests.map(choice=>({choice,before:{...context(c.s),measured:[]}})):[]}));}
